using System;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.UI;
public sealed class ResilienceTests:MonoBehaviour
{
 public static bool UseAI;static bool booted;public static bool ReadKey(KeyCode k){return false;}public static bool ReadDown(KeyCode k){return false;}
 const BindingFlags SP=BindingFlags.Static|BindingFlags.NonPublic,IP=BindingFlags.Instance|BindingFlags.NonPublic;int checks,failures;Type pt;Component fan,zhao,manager;Rigidbody2D ball;float floor,scale;ResilienceContactProbe probe;
 public static void Boot(){if(booted)return;booted=true;ControlBindings.settingsPath=System.IO.Path.Combine(Application.dataPath,"..","resilience-test.ini");var o=new GameObject("ResilienceTests");DontDestroyOnLoad(o);o.AddComponent<ResilienceTests>();}
 void Check(bool ok,string text){checks++;if(!ok)failures++;Debug.Log("ABILITY "+(ok?"PASS ":"FAIL ")+text);}
 Rigidbody2D Body(Component a){return (Rigidbody2D)pt.GetField("rb").GetValue(a);}
 void Move(Component a,Vector2 position){a.transform.position+=(Vector3)(position-Body(a).position);foreach(var b in a.GetComponentsInChildren<Rigidbody2D>()){b.velocity=Vector2.zero;b.angularVelocity=0;}Physics2D.SyncTransforms();}
 void Freeze(Component a){foreach(var b in a.GetComponentsInChildren<Rigidbody2D>())b.constraints=RigidbodyConstraints2D.FreezeAll;}
 IEnumerator Ticks(int n){for(int i=0;i<n;i++)yield return new WaitForFixedUpdate();}
 void Action(Component a,string name){PlayerSkills.SetAction((Animator)pt.GetField("anim").GetValue(a),name,a);}
 object Pending(){return typeof(SkillRework).GetField("pendingShot",SP).GetValue(null);}
 IEnumerator Scene(int mode,bool side=true,bool both=false){SkillGroups.Reset(mode==1);PlayerSkills.Enabled=mode==1;AbilityMode.Enabled=mode==2;AbilityMode.SetBudget(24);if(mode==1){SkillGroups.Set(0,side?0:1);SkillGroups.Set(1,side?1:0);}else{AbilityMode.Reset();if(mode==2){AbilityMode.Builds[side?0:1].Purchased=(1<<11)|(1<<1);if(both)AbilityMode.Builds[side?1:0].Purchased=(1<<11)|(1<<1);}}
  typeof(GameAIMod).GetMethod("BeginGame",SP).Invoke(null,new object[]{0});yield return new WaitForSeconds(.5f);pt=Type.GetType("PlayerController, Assembly-CSharp");fan=GameObject.Find("Fan").GetComponent(pt);zhao=GameObject.Find("Zhao").GetComponent(pt);manager=FindObjectOfType(pt.Assembly.GetType("GameManager")) as Component;ball=(FindObjectOfType(pt.Assembly.GetType("Ball")) as Component).GetComponent<Rigidbody2D>();floor=GameObject.Find("Down").GetComponent<Collider2D>().bounds.max.y;scale=Mathf.Abs(fan.transform.lossyScale.x)/.8f;ball.position=new Vector2(0,7);ball.velocity=Vector2.zero;ball.gravityScale=0;GameAIMod.OnBallReset();Freeze(fan);Freeze(zhao);probe=ball.gameObject.AddComponent<ResilienceContactProbe>();yield return Ticks(2);
 }
 IEnumerator HeaderBlock(Component actor,bool report=true){var other=actor==fan?zhao:fan;float dir=actor==fan?1f:-1f;Move(actor,new Vector2(-dir*2f,Body(actor).position.y));var head=actor.transform.Find("Head").GetComponent<Collider2D>();float radius=ball.GetComponent<Collider2D>().bounds.extents.y;Move(other,new Vector2(dir*2f,head.bounds.max.y+radius+.3f));ball.position=new Vector2(head.bounds.center.x,head.bounds.max.y+radius-.012f*scale);ball.velocity=Vector2.down*.5f;ball.gravityScale=0;Physics2D.SyncTransforms();int before=SkillRework.ResilienceStacks(actor),touches=probe.Count(other.name);float stamp=Time.time;Action(actor,"Head");
  yield return Ticks(3);Move(other,new Vector2(ball.position.x+dir*2.5f,ball.position.y+ball.velocity.y*.15f));int steps=0;while(steps++<70&&SkillRework.ResilienceStacks(actor)==before)yield return new WaitForFixedUpdate();
  if(report)Check(probe.Count(other.name)>touches&&SkillRework.ResilienceStacks(actor)==before+1,"actual separated cannon shot earns one block actor="+actor.name+" stacks="+SkillRework.ResilienceStacks(actor)+" contacts="+(probe.Count(other.name)-touches));
  yield return Ticks(8);if(report)Check(SkillRework.ResilienceStacks(actor)==before+1,"same blocked shot cannot farm multiple collision callbacks actor="+actor.name);ball.position=new Vector2(-dir*7f,floor+2f);ball.velocity=Vector2.zero;
 }
 IEnumerator Goal(bool right){PlayerSkills.CancelShotFlights();BuildPlayer.CancelFlights();ball.position=new Vector2(0,4);ball.velocity=Vector2.zero;int before=(int)manager.GetType().GetField("p1Score").GetValue(manager)+(int)manager.GetType().GetField("p2Score").GetValue(manager);((MonoBehaviour)manager).StartCoroutine((IEnumerator)manager.GetType().GetMethod("Goal").Invoke(manager,new object[]{right}));yield return Ticks(3);Check((int)manager.GetType().GetField("p1Score").GetValue(manager)+(int)manager.GetType().GetField("p2Score").GetValue(manager)==before+1&&SkillRework.ResilienceStacks(fan)==0&&SkillRework.ResilienceStacks(zhao)==0,"native scoring coroutine clears both players' stacks scorer="+(right?"Fan":"Zhao"));}
 IEnumerator Stacks(int mode,bool side){yield return Scene(mode,side);var a=side?fan:zhao;Check(SkillRework.Effective(a,0)==4&&SkillRework.Effective(a,2)==4,"no kickoff shooting/jumping bonus mode="+mode+" actor="+a.name);yield return HeaderBlock(a);Check(SkillRework.ShootingLevel(a)==5.5f&&SkillRework.Effective(a,1)==4&&SkillRework.Effective(a,2)==4,"one interception grants exactly fractional shooting +1.5 only actor="+a.name);yield return HeaderBlock(a,false);yield return HeaderBlock(a,false);Check(SkillRework.ResilienceStacks(a)==3&&SkillRework.ShootingLevel(a)==8.5f,"three distinct blocked shots stack beyond eight without rounding actor="+a.name+" stacks="+SkillRework.ResilienceStacks(a));
  var effects=(float[])typeof(BuildPlayer).GetField("effects",IP).GetValue(a.GetComponent<BuildPlayer>());Check(effects[11]>0&&Mathf.Abs(AbilityMode.CannonTotal(a)-16.5f)<.001f,"new skill animation and exact fractional cannon total use accumulated bonus actor="+a.name);
  GameAIMod.OnBallOut(ball.GetComponent<Collider2D>());yield return Ticks(2);GameAIMod.OnBallReset();Check(SkillRework.ResilienceStacks(a)==3&&SkillRework.ShootingLevel(a)==8.5f,"non-scoring stoppage does not erase the accumulated scoring bonus actor="+a.name);yield return Goal(side);
 }
 bool Linked(Component a,Component b){foreach(var c in a.GetComponentsInChildren<Collider2D>())if(c.enabled&&!c.isTrigger)foreach(var q in b.GetComponentsInChildren<Collider2D>())if(q.enabled&&!q.isTrigger&&c.IsTouching(q))return true;return false;}
 bool BallTouch(Component a){foreach(var c in a.GetComponentsInChildren<Collider2D>())if(c.enabled&&!c.isTrigger&&c.IsTouching(ball.GetComponent<Collider2D>()))return true;return false;}
 void BodyPair(bool air){float y=Body(fan).position.y+(air?3f*scale:0);Move(fan,new Vector2(-.5f*scale,y));Move(zhao,new Vector2(.5f*scale,y));var l=Body(fan).GetComponent<Collider2D>();var r=Body(zhao).GetComponent<Collider2D>();Move(fan,Body(fan).position+Vector2.right*(-l.bounds.max.x+.015f*scale));Move(zhao,Body(zhao).position+Vector2.right*(-r.bounds.min.x-.015f*scale));}
 IEnumerator BodyDuel(bool air){yield return Scene(2,true,true);BodyPair(air);yield return Ticks(2);var h=fan.transform.Find("Head").GetComponent<Collider2D>();ball.position=new Vector2(h.bounds.center.x,h.bounds.max.y+ball.GetComponent<Collider2D>().bounds.extents.y-.01f*scale);ball.velocity=Vector2.down*.5f;Physics2D.SyncTransforms();Action(fan,"Head");yield return Ticks(12);Check(Linked(fan,zhao)&&SkillRework.ResilienceStacks(fan)==0&&SkillRework.ResilienceStacks(zhao)==0&&Pending()==null,"body-contact header is excluded even when shot command is real air="+air);}
 IEnumerator FootDuel(){yield return Scene(2,true,true);float y=floor+ball.GetComponent<Collider2D>().bounds.extents.y+.003f;float radius=ball.GetComponent<Collider2D>().bounds.extents.x;
  foreach(var actor in new[]{fan,zhao}){bool first=actor==fan;float dir=first?1:-1;Move(actor,new Vector2(-dir*.8f,Body(actor).position.y));var shape=actor.transform.Find("L_LowLeg").GetComponent<Collider2D>();Move(actor,Body(actor).position+Vector2.up*(y-shape.bounds.center.y));var edge=shape.ClosestPoint(new Vector2(dir*100f,y));Move(actor,Body(actor).position+Vector2.right*(-dir*radius-edge.x+dir*.015f));}
  ball.position=new Vector2(0,y);ball.velocity=Vector2.zero;ball.gravityScale=1;ball.constraints=RigidbodyConstraints2D.FreezeAll;Physics2D.SyncTransforms();bool both=false;for(int i=0;i<25;i++){Action(fan,"Kick");Action(zhao,"Kick");yield return new WaitForFixedUpdate();both|=BallTouch(fan)&&BallTouch(zhao);}Check(both&&SkillRework.ResilienceStacks(fan)==0&&SkillRework.ResilienceStacks(zhao)==0,"real foot-ball-foot pushing while pressing shoot grants no stacks both="+both+" stacks="+SkillRework.ResilienceStacks(fan)+"/"+SkillRework.ResilienceStacks(zhao));}
 IEnumerator NoShots(){yield return Scene(2,true,true);for(int i=0;i<8;i++){Action(fan,"Kick");Action(zhao,"Head");yield return new WaitForFixedUpdate();}Check(SkillRework.ResilienceStacks(fan)==0&&SkillRework.ResilienceStacks(zhao)==0&&Pending()==null,"empty shot commands and ordinary possession never create a bonus");
  Move(fan,new Vector2(-5,Body(fan).position.y));var torso=Body(zhao).GetComponent<Collider2D>();ball.position=torso.ClosestPoint((Vector2)torso.bounds.center+Vector2.right*3)+Vector2.right*(ball.GetComponent<Collider2D>().bounds.extents.x-.005f);ball.velocity=Vector2.left*2f;Physics2D.SyncTransforms();yield return Ticks(6);Check(probe.Count("Zhao")>0&&SkillRework.ResilienceStacks(fan)==0&&SkillRework.ResilienceStacks(zhao)==0,"opponent touching an unshot ball is not a blocked shot");}
 IEnumerator GroundShot(bool side){bool success=false;string used="";foreach(string part in new[]{"L_Up_Leg","R_Up_Leg","L_LowLeg","R_LowLeg"}){
  yield return Scene(2,side);var a=side?fan:zhao;var other=side?zhao:fan;float dir=side?1:-1;AbilityMode.For(a).Purchased=(1<<11)|(side?1<<10:0);Move(a,new Vector2(-dir*2,Body(a).position.y));Move(other,new Vector2(dir*5,Body(other).position.y));var shape=a.transform.Find(part).GetComponent<Collider2D>();var edge=shape.ClosestPoint((Vector2)shape.bounds.center+Vector2.right*dir*3);ball.position=edge+Vector2.right*dir*(ball.GetComponent<Collider2D>().bounds.extents.x-.01f*scale);ball.velocity=Vector2.right*-dir*(side?1:6);ball.gravityScale=0;Physics2D.SyncTransforms();Action(a,"Kick");int wait=0;while(wait++<12&&Pending()==null)yield return new WaitForFixedUpdate();
  if(Pending()==null)continue;Move(other,new Vector2(ball.position.x+dir*2.5f,ball.position.y+ball.velocity.y*.3f));int steps=0;while(steps++<90&&SkillRework.ResilienceStacks(a)==0)yield return new WaitForFixedUpdate();if(SkillRework.ResilienceStacks(a)==1&&probe.Count(other.name)>0){success=true;used=part;break;}
 }Check(success,"real separated lower-body shot is tracked as well as a header actor="+(side?"Fan":"Zhao")+" contact="+used);}
 IEnumerator Both(){yield return Scene(2,true,true);yield return HeaderBlock(fan,false);yield return HeaderBlock(zhao,false);Check(SkillRework.ResilienceStacks(fan)==1&&SkillRework.ResilienceStacks(zhao)==1&&SkillRework.ShootingLevel(fan)==5.5f&&SkillRework.ShootingLevel(zhao)==5.5f,"both purchasers track their own interceptions independently");yield return Goal(false);}
 IEnumerator Guide(){var root=new GameObject("UI",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler));root.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;var proto=new GameObject("Prototype",typeof(RectTransform),typeof(Image),typeof(Button));proto.transform.SetParent(root.transform,false);var text=new GameObject("Text",typeof(RectTransform),typeof(Text));text.transform.SetParent(proto.transform,false);text.GetComponent<Text>().font=Font.CreateDynamicFontFromOSFont(new[]{"Microsoft YaHei","Arial"},22);proto.SetActive(false);var guide=SkillGuidePanel.Open(root.transform,proto.GetComponent<Button>());yield return null;bool renamed=AbilityMode.Skills[11]=="百折不挠",found=false;foreach(var label in guide.GetComponentsInChildren<Text>()){renamed&=!label.text.Contains("进攻号手");found|=label.text==SkillGuidePanel.Guide[11];foreach(char c in label.text)renamed&=!char.IsDigit(c)&&c!='%';}Check(renamed&&found&&(SkillGroups.Attack&(1<<11))!=0&&(SkillGroups.Defense&(1<<11))==0,"attack group, point shop and guide use new skill with no numerical mechanic disclosure");Destroy(root);yield return null;}
 IEnumerator Start(){Application.runInBackground=true;Application.targetFrameRate=120;QualitySettings.vSyncCount=0;AudioListener.volume=0;Time.captureFramerate=100;yield return new WaitForSeconds(.2f);yield return Guide();yield return NoShots();yield return BodyDuel(false);yield return BodyDuel(true);yield return FootDuel();yield return Stacks(1,true);yield return Stacks(1,false);yield return Stacks(2,true);yield return Stacks(2,false);yield return GroundShot(true);yield return GroundShot(false);yield return Both();Debug.Log("ABILITY COMPLETE checks="+checks+" failures="+failures);Application.Quit(failures==0?0:1);}
 void Update(){if(Time.realtimeSinceStartup>145f){Debug.LogError("ABILITY TIMEOUT");Application.Quit(2);}}
}
public sealed class ResilienceContactProbe:MonoBehaviour{int fan,zhao;public int Count(string n){return n=="Fan"?fan:zhao;}void OnCollisionEnter2D(Collision2D c){var a=c.collider.GetComponentInParent<SkillRework>();if(a!=null){if(a.name=="Fan")fan++;if(a.name=="Zhao")zhao++;}}}
